CREATE TABLE IF NOT EXISTS user_devices(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(120) NOT NULL,platform VARCHAR(32),user_agent TEXT,ip INET,last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),revoked_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS password_resets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash BYTEA NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS two_factor(id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,secret_ciphertext TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,backup_codes_hashes JSONB NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS contacts(owner_id BIGINT REFERENCES users(id) ON DELETE CASCADE,contact_id BIGINT REFERENCES users(id) ON DELETE CASCADE,alias VARCHAR(100),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(owner_id,contact_id));
CREATE TABLE IF NOT EXISTS blocks(owner_id BIGINT REFERENCES users(id) ON DELETE CASCADE,blocked_id BIGINT REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(owner_id,blocked_id));
CREATE TABLE IF NOT EXISTS reports(id BIGSERIAL PRIMARY KEY,reporter_id BIGINT REFERENCES users(id),target_user_id BIGINT REFERENCES users(id),chat_id BIGINT REFERENCES chats(id),message_id BIGINT REFERENCES messages(id),reason VARCHAR(64) NOT NULL,details TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS message_reactions(message_id BIGINT REFERENCES messages(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,emoji VARCHAR(32) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(message_id,user_id,emoji));
CREATE TABLE IF NOT EXISTS message_attachments(message_id BIGINT REFERENCES messages(id) ON DELETE CASCADE,file_id UUID REFERENCES files(id) ON DELETE CASCADE,PRIMARY KEY(message_id,file_id));
CREATE TABLE IF NOT EXISTS message_forwards(message_id BIGINT REFERENCES messages(id) ON DELETE CASCADE,source_message_id BIGINT REFERENCES messages(id),source_chat_id BIGINT REFERENCES chats(id),PRIMARY KEY(message_id));
CREATE TABLE IF NOT EXISTS chat_settings(chat_id BIGINT REFERENCES chats(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,muted BOOLEAN NOT NULL DEFAULT FALSE,archived BOOLEAN NOT NULL DEFAULT FALSE,disappearing_seconds INTEGER,topic_notifications BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(chat_id,user_id));
CREATE TABLE IF NOT EXISTS user_settings(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,settings JSONB NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS community_memberships(community_id BIGINT NOT NULL, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,managed BOOLEAN NOT NULL DEFAULT FALSE,hidden BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(community_id,user_id));
CREATE TABLE IF NOT EXISTS polls(id BIGSERIAL PRIMARY KEY,chat_id BIGINT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,creator_id BIGINT NOT NULL REFERENCES users(id),question TEXT NOT NULL,options JSONB NOT NULL,anonymous BOOLEAN NOT NULL DEFAULT FALSE,closed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS poll_votes(poll_id BIGINT REFERENCES polls(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,option_index INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(poll_id,user_id));
CREATE TABLE IF NOT EXISTS scheduled_messages(id BIGSERIAL PRIMARY KEY,chat_id BIGINT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,sender_id BIGINT NOT NULL REFERENCES users(id),body TEXT NOT NULL,send_at TIMESTAMPTZ NOT NULL,sent_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS security_events(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),type VARCHAR(64) NOT NULL,severity VARCHAR(16) NOT NULL DEFAULT 'info',ip INET,metadata JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS app_errors(id BIGSERIAL PRIMARY KEY,request_id VARCHAR(80),user_id BIGINT,route VARCHAR(255),message TEXT NOT NULL,metadata JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_security_events_user ON security_events(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_reports_open ON reports(resolved_at,created_at);
